From 4f22e6f149750401705d47ae15a60e77cd5a6905 Mon Sep 17 00:00:00 2001
From: Tomasz Stachowiak <h3@h3.gd>
Date: Sat, 1 Oct 2022 04:35:33 +0200
Subject: [PATCH] Don't break def parsing

---
 spirq/src/reflect.rs | 5 ++++-
 1 file changed, 4 insertions(+), 1 deletion(-)

diff --git a/spirq/src/reflect.rs b/spirq/src/reflect.rs
index 1a59a0a..128d00c 100644
--- a/spirq/src/reflect.rs
+++ b/spirq/src/reflect.rs
@@ -1503,7 +1503,10 @@ impl<'a> ReflectIntermediate<'a> {
             } else if SPEC_CONST_RANGE.contains(&opcode) {
                 self.populate_one_spec_const(instr)?;
             } else {
-                break;
+                // Note: Don't break. A rogue instruction like OpUndef can otherwise
+                // make us miss definitions.
+
+                //break;
             }
             instrs.next();
         }
